use clap::{Parser, Subcommand};
use anyhow::Result;

// Import the UI module directly from its source path.
#[path = "../ui/mod.rs"]
mod ui;

/// Command‑line interface for launching the MegaGate UI via the `mega` binary.
#[derive(Parser)]
#[command(name = "mega")]
#[command(author = "Generated by OpenCode")]
#[command(version = env!("CARGO_PKG_VERSION"))]
#[command(about = "CLI wrapper for UI (subcommand ui)")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Launch the interactive UI.
    #[command(name = "ui")]
    Ui,
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Commands::Ui => {
            let cwd = std::env::current_dir()?;
            ui::run_ui(cwd).await?;
        }
    }
    Ok(())
}
